def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    H, W = g.shape
    for y in range(H):
        xs = [x for x in range(W) if g[y, x] != bg]
        changed = False
        for a, b in zip(xs, xs[1:]):
            for x in range(a + 1, b):
                if out[y, x] == bg:
                    out[y, x] = 2
                    changed = True
        if changed:
            emit(out, f"Row {y}: fill the gaps between consecutive line cells (columns {xs}) with 2.")
    emit(out, "Final grid: every gap between line cells in the same row is filled with 2.")
    return out
